<?php
/**
 * VisãoOS — Instalador Único v3.0
 * 1. Faça upload deste arquivo para a raiz do site (www/) via SFTP
 * 2. Acesse: https://www.bemindmarketing.com.br/install.php?key=bemind2025
 * 3. Siga os 3 passos e APAGUE este arquivo após instalar!
 */
define('INSTALL_KEY', 'bemind2025');
if (!isset($_GET['key']) || $_GET['key'] !== INSTALL_KEY) {
    http_response_code(403); die('Acesso negado. Use ?key=bemind2025');
}

$APP_FILES = [
    'index.php' => '',
    'index.html' => '',
    '.htaccess' => '',
    'config/database.php' => '',
    'config/auth.php' => '',
    'config/notifications.php' => '',
    'config/storage.php' => '',
    'routes/auth.php' => '',
    'routes/os.php' => '',
    'routes/clients.php' => '',
    'routes/materials.php' => '',
    'routes/services.php' => '',
    'routes/quotes.php' => '',
    'routes/finance.php' => '',
    'routes/users.php' => '',
    'routes/tracking.php' => '',
    'routes/webhook.php' => '',
];

$action = $_GET['action'] ?? 'view';

// ── Escreve arquivos no disco ─────────────────────────────────────────────
if ($action === 'write_files') {
    header('Content-Type: application/json');
    $webRoot = __DIR__;
    $ok = []; $fail = [];
    foreach ($APP_FILES as $path => $b64) {
        $fullPath = $webRoot . '/' . $path;
        $dir = dirname($fullPath);
        if (!is_dir($dir)) mkdir($dir, 0755, true);
        $written = file_put_contents($fullPath, base64_decode($b64));
        if ($written !== false) $ok[] = $path; else $fail[] = $path;
    }
    foreach (['uploads', 'logs'] as $d) {
        $p = $webRoot . '/' . $d;
        if (!is_dir($p)) mkdir($p, 0775, true);
    }
    echo json_encode(['ok' => empty($fail), 'written' => count($ok), 'failed' => $fail]);
    exit;
}

// ── Testa conexão MySQL ───────────────────────────────────────────────────
if ($action === 'test_db') {
    header('Content-Type: application/json');
    $host = trim($_POST['db_host'] ?? 'localhost');
    $name = trim($_POST['db_name'] ?? 'visaoos');
    $user = trim($_POST['db_user'] ?? '');
    $pass = trim($_POST['db_pass'] ?? '');
    $err  = '';
    foreach ([
        "mysql:host=$host;dbname=$name;charset=utf8mb4",
        "mysql:host=127.0.0.1;port=3306;dbname=$name;charset=utf8mb4",
        "mysql:unix_socket=/var/run/mysqld/mysqld.sock;dbname=$name;charset=utf8mb4",
        "mysql:unix_socket=/tmp/mysql.sock;dbname=$name;charset=utf8mb4",
    ] as $dsn) {
        try {
            new PDO($dsn, $user, $pass, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
            echo json_encode(['ok' => true, 'msg' => 'Conectado!']);
            exit;
        } catch (PDOException $e) { $err = $e->getMessage(); }
    }
    echo json_encode(['ok' => false, 'msg' => $err]);
    exit;
}

// ── Instala: escreve .env + inicializa banco ──────────────────────────────
if ($action === 'install') {
    header('Content-Type: application/json');
    $host   = trim($_POST['db_host']     ?? 'localhost');
    $name   = trim($_POST['db_name']     ?? 'visaoos');
    $user   = trim($_POST['db_user']     ?? '');
    $pass   = trim($_POST['db_pass']     ?? '');
    $domain = trim($_POST['domain']      ?? 'bemindmarketing.com.br');
    $admin  = trim($_POST['admin_email'] ?? "admin@$domain");
    $webRoot = __DIR__;

    if (!file_exists($webRoot . '/config/database.php')) {
        echo json_encode(['ok' => false, 'msg' => 'Execute o Passo 1 primeiro.']);
        exit;
    }

    $jwt = bin2hex(random_bytes(32));
    $ws  = bin2hex(random_bytes(16));
    $api = bin2hex(random_bytes(24));
    $env = "APP_URL=https://$domain\nAPP_ENV=production\n\n"
         . "DB_HOST=$host\nDB_PORT=3306\nDB_NAME=$name\nDB_USER=$user\nDB_PASS=$pass\n\n"
         . "JWT_SECRET=$jwt\nJWT_EXPIRES=86400\n\n"
         . "WS_PORT=6001\nWS_SECRET=$ws\n\n"
         . "N8N_WEBHOOK_BASE=https://n8n.$domain/webhook\n"
         . "NEXTCLOUD_URL=https://cloud2.$domain\n\n"
         . "SMTP_HOST=smtp.$domain\nSMTP_PORT=587\n"
         . "SMTP_USER=noreply@$domain\nSMTP_PASS=\n"
         . "SMTP_FROM=noreply@$domain\nADMIN_EMAIL=$admin\n\n"
         . "VISAOOS_API_TOKEN=$api\n";
    file_put_contents($webRoot . '/.env', $env);
    chmod($webRoot . '/.env', 0600);

    putenv("DB_HOST=$host"); putenv("DB_NAME=$name");
    putenv("DB_USER=$user"); putenv("DB_PASS=$pass");
    putenv("APP_URL=https://$domain"); putenv("ADMIN_EMAIL=$admin");

    try {
        require_once $webRoot . '/config/database.php';
        installDB();
        // Garante que o admin usa o e-mail configurado
        $db = getDB();
        $exists = $db->prepare("SELECT id FROM users WHERE email=?");
        $exists->execute([$admin]);
        if (!$exists->fetch()) {
            $first = $db->query("SELECT id FROM users WHERE role='admin' LIMIT 1")->fetch();
            if ($first) $db->prepare("UPDATE users SET email=? WHERE id=?")->execute([$admin, $first['id']]);
        }
        echo json_encode(['ok' => true, 'email' => $admin]);
    } catch (Throwable $e) {
        echo json_encode(['ok' => false, 'msg' => $e->getMessage()]);
    }
    exit;
}
?>
<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>VisãoOS — Instalador</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Segoe UI',sans-serif;background:#f0f2f5;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px}
.wrap{width:100%;max-width:520px}
.card{background:#fff;border-radius:14px;padding:32px;box-shadow:0 4px 24px rgba(0,0,0,.09);margin-bottom:16px}
h1{color:#3b5bdb;font-size:22px;margin-bottom:4px}
.sub{color:#888;font-size:13px;margin-bottom:24px}
.steps{display:flex;gap:6px;margin-bottom:28px}
.step{flex:1;text-align:center;padding:8px 4px;border-radius:8px;font-size:12px;font-weight:700;background:#f0f2f5;color:#aaa;transition:.2s}
.step.active{background:#3b5bdb;color:#fff}
.step.done{background:#2f9e44;color:#fff}
h2{font-size:16px;color:#333;margin-bottom:16px}
