input{width:100%;padding:10px 13px;border:1.5px solid #e0e0e0;border-radius:8px;font-size:14px;outline:none;transition:border-color .2s}
input:focus{border-color:#3b5bdb}
.btn{display:block;width:100%;padding:12px;border:none;border-radius:9px;font-size:15px;font-weight:700;cursor:pointer;margin-top:16px;transition:.15s}
.btn-primary{background:#3b5bdb;color:#fff}
.btn-primary:hover{background:#2f4ac7}
.btn-green{background:#2f9e44;color:#fff}
.btn-green:hover{background:#237a33}
.btn:disabled{opacity:.6;cursor:not-allowed}
.msg{padding:11px 14px;border-radius:8px;font-size:13px;margin-top:12px;display:none}
.msg.show{display:block}
.ok{background:#ebfbee;color:#2f9e44;border:1px solid #b2f2bb}
.err{background:#fff5f5;color:#c92a2a;border:1px solid #ffc9c9}
