a.site-btn{display:block;text-align:center;background:#2f9e44;color:#fff;padding:13px;border-radius:9px;text-decoration:none;font-weight:700;font-size:15px;margin-top:16px}
.file-list{font-size:12px;color:#555;margin-top:10px;max-height:120px;overflow-y:auto;background:#f8f9fa;border-radius:8px;padding:10px}
.pane{display:none}.pane.active{display:block}
</style>
</head>
<body>
<div class="wrap">
  <div class="card">
    <h1>VisãoOS</h1>
    <div class="sub">Instalador — bemindmarketing.com.br</div>
    <div class="steps">
      <div class="step active" id="s1">1. Arquivos</div>
      <div class="step" id="s2">2. Banco</div>
      <div class="step" id="s3">3. Concluído</div>
    </div>

    <!-- PASSO 1 -->
    <div class="pane active" id="pane1">
      <h2>Instalar Arquivos do Sistema</h2>
      <p style="font-size:13px;color:#555">Escreve todos os arquivos PHP, HTML e configurações na raiz do site.</p>
      <button class="btn btn-primary" id="btn1" onclick="installFiles()">Instalar Arquivos</button>
      <div class="msg" id="msg1"></div>
      <div class="file-list" id="file-list" style="display:none"></div>
    </div>

    <!-- PASSO 2 -->
    <div class="pane" id="pane2">
      <h2>Configurar Banco de Dados</h2>
      <label>Host MySQL</label>
      <input id="db_host" value="localhost">
      <label>Nome do Banco</label>
      <input id="db_name" value="visaoos">
      <label>Usuário MySQL</label>
      <input id="db_user" value="visaoos26">
      <label>Senha MySQL</label>
      <input id="db_pass" type="password" value="Visaoos2025">
      <label>Domínio</label>
      <input id="domain" value="bemindmarketing.com.br">
      <label>E-mail do Admin</label>
      <input id="admin_email" value="admin@bemindmarketing.com.br">
      <button class="btn btn-primary" id="btn-test" onclick="testDb()" style="margin-top:14px">Testar Conexão</button>
      <button class="btn btn-green" id="btn2" onclick="installDb()" disabled>Instalar Banco</button>
      <div class="msg" id="msg2"></div>
    </div>

    <!-- PASSO 3 -->
    <div class="pane" id="pane3">
      <h2>✅ Instalação Concluída!</h2>
      <div class="cred-box">
        🌐 Site: <code>https://bemindmarketing.com.br</code><br>
        👤 Login: <code id="cred-email">admin@bemindmarketing.com.br</code><br>
        🔑 Senha: <code>admin123</code>
      </div>
      <a class="site-btn" href="https://www.bemindmarketing.com.br" target="_blank">Acessar o Sistema →</a>
      <div class="warn-box">
        ⚠️ <strong>Troque a senha <code>admin123</code> após o primeiro login e apague este arquivo <code>install.php</code> do servidor.</strong>
      </div>
    </div>
  </div>
</div>
<script>
const key = '<?= htmlspecialchars($_GET['key']) ?>';
const base = location.pathname.replace('install.php','');

function setStep(n) {
  [1,2,3].forEach(i => {
    document.getElementById('pane'+i).classList.toggle('active', i===n);
    const s = document.getElementById('s'+i);
    s.className = 'step' + (i===n?' active':i<n?' done':'');
  });
}

function showMsg(id, type, text) {
  const el = document.getElementById(id);
  el.className = 'msg show ' + type;
  el.textContent = text;
}

async function installFiles() {
  const btn = document.getElementById('btn1');
  btn.disabled = true; btn.textContent = 'Instalando...';
  showMsg('msg1','info','Escrevendo arquivos...');
  try {
    const r = await fetch(`${base}install.php?key=${key}&action=write_files`);
    const d = await r.json();
    if (d.ok) {
      showMsg('msg1','ok','✅ ' + d.written + ' arquivos instalados!');
      const fl = document.getElementById('file-list');
      fl.style.display='block';
      fl.textContent = 'Arquivos: ' + (d.written || '');
      setTimeout(()=>setStep(2), 800);
    } else {
      showMsg('msg1','err','❌ Falha: ' + (d.failed||[]).join(', '));
      btn.disabled=false; btn.textContent='Tentar Novamente';
    }
  } catch(e) {
    showMsg('msg1','err','❌ ' + e.message);
    btn.disabled=false; btn.textContent='Tentar Novamente';
  }
}

async function testDb() {
  const btn = document.getElementById('btn-test');
  const btn2 = document.getElementById('btn2');
  btn.disabled=true; btn.textContent='Testando...';
  btn2.disabled=true;
  const fd = new FormData();
  ['db_host','db_name','db_user','db_pass'].forEach(k=>fd.append(k,document.getElementById(k).value));
  try {
    const r = await fetch(`${base}install.php?key=${key}&action=test_db`,{method:'POST',body:fd});
    const d = await r.json();
    if (d.ok) {
      showMsg('msg2','ok','✅ Conexão OK!');
      btn2.disabled=false;
    } else {
      showMsg('msg2','err','❌ ' + d.msg);
    }
  } catch(e) { showMsg('msg2','err','❌ ' + e.message); }
  btn.disabled=false; btn.textContent='Testar Conexão';
}

async function installDb() {
  const btn = document.getElementById('btn2');
  btn.disabled=true; btn.textContent='Instalando...';
  showMsg('msg2','info','Configurando banco...');
  const fd = new FormData();
  ['db_host','db_name','db_user','db_pass','domain','admin_email'].forEach(k=>fd.append(k,document.getElementById(k).value));
  try {
    const r = await fetch(`${base}install.php?key=${key}&action=install`,{method:'POST',body:fd});
    const d = await r.json();
    if (d.ok) {
      document.getElementById('cred-email').textContent = d.email || 'admin@bemindmarketing.com.br';
      setStep(3);
    } else {
      showMsg('msg2','err','❌ ' + d.msg);
      btn.disabled=false; btn.textContent='Instalar Banco';
    }
  } catch(e) {
    showMsg('msg2','err','❌ ' + e.message);
    btn.disabled=false; btn.textContent='Instalar Banco';
  }
}
</script>
</body>
